function markBackendUnavailable(error) {
  backendApiState.status = 'error';
  backendApiState.lastError = BACKEND_READ_FAILED_MESSAGE;
}

function failBackendRequiredWrite(error, stateRef = null, fallbackMessage = 'Backend save failed. Nothing was saved locally.') {
  const message = error?.message || fallbackMessage;
  if (stateRef) {
    stateRef.status = error ? 'error' : 'auth';
    stateRef.lastError = message;
  }
  toast(message);
  return false;
}

function requireBackendWriteSession(stateRef = null, message = 'Sign in before saving. Nothing was saved locally.') {
  if (backendAuthState.token && backendAuthState.user) return true;
  return failBackendRequiredWrite(null, stateRef, message);
}

function requireEmployeeBackendWrite(stateRef = null, message = 'Sign in as an employee or admin before saving. Nothing was saved locally.') {
  if (backendAuthState.token && backendAuthState.user?.userType !== 'customer') return true;
  return failBackendRequiredWrite(null, stateRef, message);
}

const BACKEND_READ_FAILED_MESSAGE = 'Backend read failed. No local or preview data is shown.';

function setBackendReadFailed(stateRef) {
  if (!stateRef) return;
  stateRef.status = 'error';
  stateRef.lastError = BACKEND_READ_FAILED_MESSAGE;
  stateRef.loading = false;
  stateRef.loaded = true;
}

function clearProtectedBackendRows(area) {
  switch (area) {
    case 'account-management':
      state.users = [];
      break;
    case 'customers':
      state.customers = [];
      break;
    case 'products':
      state.products = [];
      state.boms = {};
      break;
    case 'master-items':
      state.masterItems = [];
      break;
    case 'inventory':
      state.ingredients = [];
      state.receivingLog = [];
      state.moveLog = [];
      backendInventoryState.signals = null;
      break;
    case 'procurement':
      state.procurementOrders = [];
      backendProcurementState.needRows = [];
      break;
    case 'production':
      backendProductionState.runs = [];
      backendProductionState.logs = [];
      state.productionLog = [];
      state.purchaseOrders = [];
      break;
    case 'quality':
      backendQualityState.queue = [];
      state.purchaseOrders = [];
      break;
    case 'shipping':
      backendShippingState.queue = [];
      backendShippingState.logs = [];
      state.shippingLog = [];
      state.purchaseOrders = [];
      break;
    case 'pick-pack':
      backendPickPackState.orders = [];
      state.pickPackOrders = [];
      break;
    case 'research':
      backendResearchState.requests = [];
      state.rdRequests = [];
      break;
    case 'purchase-orders':
      state.purchaseOrders = [];
      break;
  }
}

