function backendPurchaseOrderId(po) {
  return po?._backendId || po?.id || '';
}

function mergeBackendPurchaseOrders(records) {
  const backendPos = (records || []).map(mapBackendPurchaseOrderToPrototype);
  const backendIds = new Set(backendPos.map(po => po._backendId));
  state.purchaseOrders = [
    ...backendPos,
    ...state.purchaseOrders.filter(po => !po._backendId || !backendIds.has(po._backendId))
  ];
  try { saveState(); } catch (err) {}
  return backendPos;
}

function mapBackendPurchaseOrderToPrototype(po) {
  const backendStatus = po.status || 'draft';
  const existing = (state.purchaseOrders || []).find(local => local._backendId === po.id || local.id === po.poNumber || local.id === po.id) || {};
  const shippingDetails = po.shippingDetails || {};
  const shippingPalletList = parseJsonFallback(shippingDetails.palletListJson, []);
  const backendShipping = {
    ...(existing.shipping || {}),
    bol: shippingDetails.bolNumber || existing.shipping?.bol || '',
    proNumber: shippingDetails.proNumber || existing.shipping?.proNumber || '',
    carrier: shippingDetails.carrier || existing.shipping?.carrier || '',
    freightClass: shippingDetails.freightClass || existing.shipping?.freightClass || '',
    notes: shippingDetails.notes || po.shippingNotes || existing.shipping?.notes || '',
    palletList: shippingPalletList.length ? shippingPalletList : existing.shipping?.palletList,
    shipmentDocumentFileId: po.shipmentDocumentFileId || shippingDetails.shipmentDocumentFileId || existing.shipping?.shipmentDocumentFileId || ''
  };
  const prototypeStatus = backendStatus === 'approved_for_production'
    ? 'approved_for_production'
    : backendStatus === 'in_production'
      ? 'in_production'
      : backendStatus === 'qa_review'
        ? 'qa_review'
    : backendStatus === 'cancelled'
      ? 'cancelled'
    : backendStatus === 'shipping'
      ? 'shipping'
    : backendStatus === 'completed'
      ? 'completed'
      : 'in_supply_chain';
  return {
    id: po.poNumber || po.id,
    _backendId: po.id,
    _backendSource: true,
    _backendStatus: backendStatus,
    _backendLines: po.lines || [],
    brand: '',
    customerId: po.customerId || '',
    poDate: new Date().toISOString().slice(0, 10),
    requestedDate: po.requestedShipDate || '',
    requestedShipDate: po.requestedShipDate || '',
    notes: po.notes || '',
    lines: (po.lines || []).map(line => ({
      id: line.id,
      productId: line.productId || '',
      qty: line.quantity || 0,
      price: 0,
      description: line.description || '',
      masterItemId: line.masterItemId || null,
      supply_chain_status: line.supplyChainStatus || 'pending'
    })),
    status: prototypeStatus,
    productionDate: po.productionDate || existing?.productionDate || null,
    productionEndDate: po.productionEndDate || existing?.productionEndDate || null,
    productionRoom: po.productionRoom || existing?.productionRoom || null,
    productionFinalized: backendStatus === 'qa_review' ? true : !!existing?.productionFinalized,
    depositStatus: mapBackendDepositToPrototype(po.depositStatus),
    poFile: null,
    _backendFiles: [],
    scOverrides: {},
    qaNotes: po.qaNotes || existing?.qaNotes || '',
    qaReleasedAt: po.qaReleasedAt || existing?.qaReleasedAt || '',
    qaReleasedByUserId: po.qaReleasedByUserId || existing?.qaReleasedByUserId || '',
    qaReleaseType: po.qaReleaseType || existing?.qaReleaseType || '',
    qaSkippedAt: po.qaSkippedAt || existing?.qaSkippedAt || '',
    qaSkippedByUserId: po.qaSkippedByUserId || existing?.qaSkippedByUserId || '',
    qaSkipReason: po.qaSkipReason || existing?.qaSkipReason || '',
    postShipmentCoaFileId: po.postShipmentCoaFileId || existing?.postShipmentCoaFileId || '',
    shipping: backendShipping,
    shippedAt: po.shippedAt || existing?.shippedAt || '',
    stockedAt: po.stockedAt || existing?.stockedAt || ''
  };
}

function mapBackendDepositToPrototype(status) {
  return ['not_required', 'received', 'waived'].includes(status) ? 'ok' : 'on_hold';
}

function mapPrototypeDepositToBackend(status) {
  return status === 'ok' ? 'received' : 'required';
}

function buildBackendPurchaseOrderPayload(localPo) {
  return {
    poNumber: localPo.id,
    customerId: localPo.customerId,
    requestedShipDate: localPo.requestedDate || null,
    notes: localPo.notes || null,
    actorUserId: BACKEND_ACTOR_USER_ID,
    lines: (localPo.lines || []).map(line => {
      const product = getProduct(line.productId);
      return {
        description: product?.name || line.description || line.productId || 'Purchase order line',
        quantity: Number(line.qty || line.quantity || 0),
        unitOfMeasure: line.unitOfMeasure || 'Each',
        productId: line.productId || null,
        masterItemId: line.masterItemId || null
      };
    })
  };
}

async function uploadBackendPurchaseOrderFile(purchaseOrderId, file) {
  if (!file) return null;
  const form = new FormData();
  form.set('ownerType', 'purchase_order');
  form.set('ownerId', purchaseOrderId);
  form.set('fileCategory', 'po_file');
  form.set('file', file);
  return apiFormRequest('/api/files', form);
}

async function loadBackendPurchaseOrderFiles(purchaseOrderId) {
  return apiRequest(`/api/files?ownerType=purchase_order&ownerId=${encodeURIComponent(purchaseOrderId)}`);
}

async function attachBackendFilesToPurchaseOrder(localPo) {
  const purchaseOrderId = backendPurchaseOrderId(localPo);
  if (!purchaseOrderId) return localPo;
  const files = await loadBackendPurchaseOrderFiles(purchaseOrderId);
  localPo._backendFiles = files || [];
  const firstPoFile = (files || []).find(file => file.fileCategory === 'po_file') || files?.[0] || null;
  localPo.poFile = firstPoFile ? mapBackendFileToPrototype(firstPoFile) : localPo.poFile || null;
  return localPo;
}

async function hydrateBackendPurchaseOrderFiles(localPos) {
  for (const po of localPos || []) {
    try {
      await attachBackendFilesToPurchaseOrder(po);
    } catch (error) {
      po._backendFileError = error?.message || 'PO files unavailable';
    }
  }
}

function mapBackendFileToPrototype(file) {
  const downloadUrl = backendFileHref(file);
  return {
    _backendFileId: file.id,
    _backendOwnerId: file.ownerId,
    _backendFile: true,
    fileId: file.id,
    name: file.fileName,
    type: file.contentType || '',
    size: file.sizeBytes || 0,
    uploadedAt: file.createdAt,
    fileCategory: file.fileCategory,
    dataUrl: downloadUrl,
    downloadUrl
  };
}

function backendFileId(file) {
  return typeof file === 'string' ? file : file?.fileId || file?._backendFileId || file?.id || '';
}

function backendFileName(file, fallback = 'file') {
  return file?.name || file?.fileName || fallback;
}

function backendFileHref(file) {
  const fileId = backendFileId(file);
  return fileId ? `/api/files/${encodeURIComponent(fileId)}/download` : '';
}

async function fetchBackendFileBlob(fileId) {
  const response = await fetch(`/api/files/${encodeURIComponent(fileId)}/download`, {
    headers: {
      ...authHeaders()
    }
  });
  if (!response.ok) {
    throw new Error(`File download failed (${response.status})`);
  }
  return response.blob();
}

async function downloadBackendFile(fileId, fileName) {
  const blob = await fetchBackendFileBlob(fileId);
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.href = url;
  link.download = fileName || 'download';
  document.body.appendChild(link);
  link.click();
  link.remove();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}

async function previewBackendFile(fileId, fileName, contentType = '') {
  const blob = await fetchBackendFileBlob(fileId);
  const previewBlob = contentType && blob.type !== contentType
    ? blob.slice(0, blob.size, contentType)
    : blob;
  const url = URL.createObjectURL(previewBlob);
  const preview = window.open(url, '_blank');
  if (!preview) {
    URL.revokeObjectURL(url);
    throw new Error('Popup blocked. Allow popups to preview this file.');
  }
  preview.addEventListener('beforeunload', () => URL.revokeObjectURL(url), { once: true });
  setTimeout(() => URL.revokeObjectURL(url), 60000);
  return preview;
}

function backendFileActionHtml(file, options = {}) {
  if (!file) return options.emptyHtml || '';
  const fileId = backendFileId(file);
  const name = backendFileName(file, options.fallbackLabel || 'file');
  const text = options.htmlLabel || escapeHtml(options.label || name);
  const className = options.className ? ` class="${escapeHtml(options.className)}"` : '';
  const style = options.style ? ` style="${escapeHtml(options.style)}"` : '';
  const title = escapeHtml(options.title || name);
  if (fileId) {
    const mode = options.mode === 'preview' ? 'preview' : 'download';
    return `<button type="button"${className}${style} title="${title}" data-backend-file-id="${escapeHtml(fileId)}" data-backend-file-name="${escapeHtml(name)}" data-backend-file-type="${escapeHtml(file.type || '')}" data-backend-file-mode="${mode}" onclick="handleBackendFileAction(this)">${text}</button>`;
  }
  if (file.dataUrl) {
    const target = options.mode === 'preview' ? ' target="_blank" rel="noopener"' : '';
    const download = options.mode === 'preview' ? '' : ` download="${escapeHtml(name)}"`;
    return `<a${className}${style} href="${file.dataUrl}"${download} title="${title}"${target}>${text}</a>`;
  }
  return options.unavailableHtml || `<span style="color:var(--brown-light);font-size:12px">${escapeHtml(name)} unavailable</span>`;
}

async function handleBackendFileAction(button) {
  const fileId = button?.dataset?.backendFileId || '';
  const fileName = button?.dataset?.backendFileName || 'download';
  const contentType = button?.dataset?.backendFileType || '';
  const mode = button?.dataset?.backendFileMode || 'download';
  try {
    if (mode === 'preview') await previewBackendFile(fileId, fileName, contentType);
    else await downloadBackendFile(fileId, fileName);
  } catch (error) {
    toast(error?.message || 'File action failed.');
  }
}

async function ensureBackendPurchaseOrdersLoaded() {
  if (backendApiState.loadedPurchaseOrders || backendApiState.loadingPurchaseOrders) return;
  backendApiState.loadingPurchaseOrders = true;
  try {
    const records = await apiRequest('/api/purchase-orders');
    const backendPos = mergeBackendPurchaseOrders(records);
    await hydrateBackendPurchaseOrderFiles(backendPos);
    backendApiState.loadedPurchaseOrders = true;
    if (currentPage === 'purchase-orders') renderPurchaseOrders(document.getElementById('content'));
    if (currentPage === 'supply-chain') renderSupplyChain(document.getElementById('content'));
  } catch (error) {
    markBackendUnavailable(error);
    clearProtectedBackendRows('purchase-orders');
    backendApiState.loadedPurchaseOrders = true;
  } finally {
    backendApiState.loadingPurchaseOrders = false;
    if (currentPage === 'purchase-orders') renderPurchaseOrders(document.getElementById('content'));
    if (currentPage === 'supply-chain') renderSupplyChain(document.getElementById('content'));
  }
}

async function refreshBackendPurchaseOrders() {
  backendApiState.loadedPurchaseOrders = false;
  await ensureBackendPurchaseOrdersLoaded();
}

async function createBackendPurchaseOrder(localPo) {
  const created = await apiRequest('/api/purchase-orders', {
    method: 'POST',
    body: JSON.stringify(buildBackendPurchaseOrderPayload(localPo))
  });
  const uploadFile = localPo._pendingUploadFile || (localPo.poFile instanceof File ? localPo.poFile : null);
  if (uploadFile) {
    try {
      await uploadBackendPurchaseOrderFile(created.id, uploadFile);
    } catch (error) {
      throw new Error(`Backend PO was created as draft, but file upload failed: ${error.message}`);
    }
  }
  const submitted = await apiRequest(`/api/purchase-orders/${encodeURIComponent(created.id)}/submit`, {
    method: 'POST',
    body: JSON.stringify({ actorUserId: BACKEND_ACTOR_USER_ID })
  });
  const merged = mergeBackendPurchaseOrders([submitted]);
  await hydrateBackendPurchaseOrderFiles(merged);
  return submitted;
}

async function updateBackendPurchaseOrder(localPo) {
  const purchaseOrderId = backendPurchaseOrderId(localPo);
  const updated = await apiRequest(`/api/purchase-orders/${encodeURIComponent(purchaseOrderId)}`, {
    method: 'PATCH',
    body: JSON.stringify({
      notes: localPo.notes || null,
      requestedShipDate: localPo.requestedDate || null,
      actorUserId: BACKEND_ACTOR_USER_ID
    })
  });
  mergeBackendPurchaseOrders([updated]);
  return updated;
}

async function readBackendPurchaseOrder(po) {
  const purchaseOrderId = backendPurchaseOrderId(po);
  const record = await apiRequest(`/api/purchase-orders/${encodeURIComponent(purchaseOrderId)}`);
  const merged = mergeBackendPurchaseOrders([record]);
  await hydrateBackendPurchaseOrderFiles(merged);
  return merged[0];
}

async function createBackendPurchaseOrderChangeRequest(purchaseOrderId, requestType, message) {
  return apiRequest(`/api/purchase-orders/${encodeURIComponent(purchaseOrderId)}/change-requests`, {
    method: 'POST',
    body: JSON.stringify({ requestType, message })
  });
}

async function updateBackendDepositStatus(po, status) {
  const purchaseOrderId = backendPurchaseOrderId(po);
  const updated = await apiRequest(`/api/purchase-orders/${encodeURIComponent(purchaseOrderId)}/deposit-status`, {
    method: 'POST',
    body: JSON.stringify({ depositStatus: mapPrototypeDepositToBackend(status), actorUserId: BACKEND_ACTOR_USER_ID })
  });
  mergeBackendPurchaseOrders([updated]);
  return updated;
}

async function cancelBackendPurchaseOrder(po) {
  const purchaseOrderId = backendPurchaseOrderId(po);
  if (!purchaseOrderId) throw new Error('Backend purchase order cancellation is unavailable for this PO.');
  const updated = await apiRequest(`/api/purchase-orders/${encodeURIComponent(purchaseOrderId)}/cancel`, {
    method: 'POST',
    body: JSON.stringify({ actorUserId: BACKEND_ACTOR_USER_ID })
  });
  mergeBackendPurchaseOrders([updated]);
  backendApiState.loadedPurchaseOrders = false;
  return updated;
}

async function reviewBackendSupplyChainLines(po, supplyChainStatus) {
  const purchaseOrderId = backendPurchaseOrderId(po);
  const lines = po?._backendLines || [];
  for (const line of lines) {
    await apiRequest(`/api/purchase-orders/${encodeURIComponent(purchaseOrderId)}/lines/${encodeURIComponent(line.id)}/supply-chain-review`, {
      method: 'POST',
      body: JSON.stringify({ supplyChainStatus, actorUserId: BACKEND_ACTOR_USER_ID })
    });
  }
  await refreshBackendPurchaseOrders();
}

async function approveBackendPurchaseOrder(po) {
  const purchaseOrderId = backendPurchaseOrderId(po);
  const approved = await apiRequest(`/api/purchase-orders/${encodeURIComponent(purchaseOrderId)}/approve-for-production`, {
    method: 'POST',
    body: JSON.stringify({ actorUserId: BACKEND_ACTOR_USER_ID })
  });
  mergeBackendPurchaseOrders([approved]);
  return approved;
}

/* js/ui/utilities.js */
/* =========================================================================
   UTILITIES
   ========================================================================= */
function uid(prefix = '') {
  return prefix + Math.random().toString(36).slice(2, 9);
}
function nextPoId() {
  const nums = state.purchaseOrders
    .map(p => parseInt((p.id.match(/\d+/) || [0])[0], 10))
    .filter(n => !isNaN(n));
  const next = (nums.length ? Math.max(...nums) : 1000) + 1;
  return 'PO-' + next;
}
function fmtMoney(n) {
  return '$' + Number(n || 0).toFixed(2);
}
function fmtDate(d) {
  if (!d) return '-';
  const dt = new Date(d + 'T00:00:00');
  return dt.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
}
function statusBadge(s) {
  const map = {
    draft: ['Draft', 'badge-pending'],
    submitted: ['Submitted', 'badge-supply'],
    supply_chain_review: ['Supply Chain', 'badge-supply'],
    pending: ['Pending Review', 'badge-pending'],
    in_supply_chain: ['Supply Chain', 'badge-supply'],
    approved_for_production: ['Approved', 'badge-prod'],
    in_production: ['In Production', 'badge-prod'],
    qa_review: ['QA Review', 'badge-pending'],
    shipping: ['Ready to Ship', 'badge-shipping'],
    completed: ['Completed', 'badge-complete']
  };
  const [label, cls] = map[s] || [s, 'badge-complete'];
  return `<span class="badge ${cls}">${label}</span>`;
}
function getCustomer(id) { return state.customers.find(c => c.id === id); }
function getProduct(id) { return state.products.find(p => p.id === id); }
function getSupplier(id) { return state.suppliers.find(s => s.id === id); }
function getIngredient(id) { return state.ingredients.find(i => i.id === id); }
function escapeHtml(s) {
  if (s == null) return '';
  return String(s)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;').replace(/'/g, '&#039;');
}
function toast(msg) {
  const t = document.getElementById('toast');
  t.textContent = msg;
  t.classList.add('show');
  setTimeout(() => t.classList.remove('show'), 2200);
}

function getModalFocusableElements() {
  const modal = document.getElementById('modal');
  if (!modal?.classList.contains('open')) return [];
  return Array.from(modal.querySelectorAll('a[href], button:not([disabled]), input:not([disabled]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex="-1"])'))
    .filter(el => el.offsetParent !== null || el === document.activeElement);
}

function captureModalFieldState(root) {
  return Array.from(root.querySelectorAll('input, textarea, select')).map((el, index) => ({
    index,
    id: el.id || '',
    name: el.getAttribute('name') || '',
    value: el.value,
    checked: Boolean(el.checked),
    selectedIndex: typeof el.selectedIndex === 'number' ? el.selectedIndex : -1
  }));
}

function restoreModalFieldState(root, fieldState = []) {
  const fields = Array.from(root.querySelectorAll('input, textarea, select'));
  fieldState.forEach(saved => {
    const field = (saved.id && root.querySelector(`#${CSS.escape(saved.id)}`))
      || (saved.name && root.querySelector(`[name="${CSS.escape(saved.name)}"]`))
      || fields[saved.index];
    if (!field) return;
    if ('checked' in field) field.checked = saved.checked;
    if ('value' in field) field.value = saved.value;
    if (saved.selectedIndex >= 0 && 'selectedIndex' in field) field.selectedIndex = saved.selectedIndex;
  });
}

function focusFirstModalElement() {
  const focusable = getModalFocusableElements();
  const target = focusable[0] || document.querySelector('.modal');
  if (target?.focus) target.focus({ preventScroll: true });
}

function trapModalFocus(event) {
  if (event.key === 'Escape') {
    event.preventDefault();
    event.stopPropagation();
    closeModal();
    return;
  }
  if (event.key !== 'Tab') return;
  const focusable = getModalFocusableElements();
  if (!focusable.length) {
    event.preventDefault();
    return;
  }
  const first = focusable[0];
  const last = focusable[focusable.length - 1];
  if (event.shiftKey && document.activeElement === first) {
    event.preventDefault();
    last.focus();
  } else if (!event.shiftKey && document.activeElement === last) {
    event.preventDefault();
    first.focus();
  }
}

function openConfirmModal({
  title = 'Confirm action',
  record = '',
  message = '',
  risk = '',
  confirmLabel = 'Confirm',
  cancelLabel = 'Cancel',
  tone = 'danger'
} = {}) {
  if (confirmModalResolver) resolveConfirmModal(false);
  const overlay = document.getElementById('modal');
  const activeElement = document.activeElement;
  if (activeElement && !overlay.contains(activeElement)) {
    lastModalTrigger = activeElement;
  }
  const modal = document.querySelector('.modal');
  confirmModalPreviousState = {
    open: overlay.classList.contains('open'),
    modalClass: modal?.className || 'modal',
    title: document.getElementById('modalTitle').innerHTML,
    body: document.getElementById('modalBody').innerHTML,
    fieldState: captureModalFieldState(overlay)
  };
  if (modal) modal.className = 'modal confirm-modal';
  document.getElementById('modalTitle').textContent = title;
  document.getElementById('modalBody').innerHTML = `
    <div class="erp-confirm-modal" data-confirm-action="${escapeAttr(title)}">
      ${record ? `<div class="confirm-record">${escapeHtml(record)}</div>` : ''}
      <div class="confirm-message">${escapeHtml(message)}</div>
      ${risk ? `<div class="confirm-risk">${escapeHtml(risk)}</div>` : ''}
      <div class="confirm-actions">
        <button class="btn btn-secondary" type="button" onclick="resolveConfirmModal(false)">${escapeHtml(cancelLabel)}</button>
        <button class="btn ${tone === 'danger' ? 'btn-danger' : 'btn-workflow'}" type="button" onclick="resolveConfirmModal(true)">${escapeHtml(confirmLabel)}</button>
      </div>
    </div>`;
  overlay.classList.add('open');
  setTimeout(focusFirstModalElement, 0);
  return new Promise(resolve => {
    confirmModalResolver = resolve;
  });
}

function resolveConfirmModal(result) {
  const resolver = confirmModalResolver;
  confirmModalResolver = null;
  const overlay = document.getElementById('modal');
  const modal = document.querySelector('.modal');
  if (confirmModalPreviousState?.open) {
    if (modal) modal.className = confirmModalPreviousState.modalClass;
    document.getElementById('modalTitle').innerHTML = confirmModalPreviousState.title;
    document.getElementById('modalBody').innerHTML = confirmModalPreviousState.body;
    restoreModalFieldState(overlay, confirmModalPreviousState.fieldState);
    overlay.classList.add('open');
    setTimeout(focusFirstModalElement, 0);
  } else {
    overlay.classList.remove('open');
    if (modal) modal.className = 'modal stitch-modal';
    if (lastModalTrigger?.focus) lastModalTrigger.focus({ preventScroll: true });
  }
  confirmModalPreviousState = null;
  if (resolver) resolver(Boolean(result));
}

/* js/state/inventory-helpers.js */
/* =========================================================================
   INVENTORY HELPERS
   ========================================================================= */
function poRequirements(po, useActual, withLoss) {
  const required = {};
  const factor = withLoss ? PLANNING_LOSS_FACTOR : 1;
  po.lines.forEach(line => {
    const bom = state.boms[line.productId] || [];
    const qty = (useActual && typeof line.actualQty === 'number') ? line.actualQty : line.qty;
    bom.forEach(b => {
      required[b.ingredientId] = (required[b.ingredientId] || 0) + b.qty * qty * factor;
    });
  });
  return required;
}
// Theoretical (no loss buffer) requirements - used to compute waste vs. actual at completion
function poTheoretical(po, useActual) { return poRequirements(po, useActual, false); }
function inventoryCheck(po) {
  const req = poRequirements(po);
  const issues = [];
  Object.keys(req).forEach(ingId => {
    const ing = getIngredient(ingId);
    if (!ing) return;
    if (ing.stock < req[ingId]) {
      issues.push({ ingredient: ing, needed: req[ingId], short: req[ingId] - ing.stock });
    }
  });
  return issues;
}
function consumeInventory(po) {
  // Prefer the ACTUAL materials used (captured at completion) for accurate deduction.
  if (Array.isArray(po.materialsUsed) && po.materialsUsed.length) {
    po.materialsUsed.forEach(m => {
      const ing = getIngredient(m.ingredientId);
      if (ing) ing.stock = Math.max(0, (ing.stock||0) - (parseFloat(m.actual)||0));
    });
    return;
  }
  // Fallback (legacy): theoretical requirement based on actual finished-good qty.
  const req = poRequirements(po, true);
  Object.keys(req).forEach(ingId => {
    const ing = getIngredient(ingId);
    if (ing) ing.stock = Math.max(0, ing.stock - req[ingId]);
  });
}

/* =========================================================================
   INVENTORY RESERVATION (multi-PO allocation tracking)
   - "Allocated" = ingredients committed to POs that haven't yet deducted inventory
   - That's any PO with status approved_for_production or in_production (and not finalized)
   - At ship/complete, inventory is already deducted, so those POs no longer count as allocating
   - At pending/in_supply_chain, the PO hasn't been approved yet so it's not committed
   ========================================================================= */
function isAllocating(po) {
  if (!po) return false;
  if (po.productionFinalized) return false;
  return po.status === 'approved_for_production' || po.status === 'in_production';
}
// Sum of allocated qty per ingredient across every active PO. Optionally exclude one PO (when checking that PO itself).
function allocatedInventory(excludePoId) {
  const allocated = {};
  state.purchaseOrders.forEach(po => {
    if (excludePoId && po.id === excludePoId) return;
    if (!isAllocating(po)) return;
    const req = poRequirements(po, false, true); // include 5% planning loss buffer
    Object.keys(req).forEach(ingId => {
      allocated[ingId] = (allocated[ingId] || 0) + req[ingId];
    });
  });
  return allocated;
}
// Net available for an ingredient (on hand minus other-PO allocations)
function netAvailableFor(ingredientId, excludePoId) {
  const ing = getIngredient(ingredientId);
  if (!ing) return 0;
  const alloc = allocatedInventory(excludePoId);
  return (ing.stock || 0) - (alloc[ingredientId] || 0);
}
// Demand from POs still awaiting Supply Chain approval (pending / in_supply_chain).
// These aren't "allocated" yet, but if we don't have enough to cover them, Procurement should order.
function supplyChainDemand() {
  const demand = {};
  state.purchaseOrders.forEach(po => {
    if (po.status !== 'pending' && po.status !== 'in_supply_chain') return;
    const req = poRequirements(po, false, true); // include 5% planning loss buffer
    Object.keys(req).forEach(ingId => { demand[ingId] = (demand[ingId] || 0) + req[ingId]; });
  });
  return demand;
}
// Which Supply Chain POs need a given ingredient (for "why" labels in Procurement)
function scPOsNeedingIngredient(ingId) {
  return state.purchaseOrders.filter(po => {
    if (po.status !== 'pending' && po.status !== 'in_supply_chain') return false;
    return (poRequirements(po)[ingId] || 0) > 0;
  });
}
// DISPLAY-ONLY total allocation per ingredient for the Inventory page:
// anything tied up by a PO that hasn't shipped yet - Supply Chain reviews +
// approved + in-production. Includes the 5% planning loss buffer.
// (Does NOT affect Supply Chain approval gating, which still uses allocatedInventory().)
function inventoryAllocation() {
  const total = {};
  const prod = allocatedInventory();           // approved_for_production + in_production
  const sc = supplyChainDemand();              // pending / in_supply_chain
  Object.keys(prod).forEach(id => { total[id] = (total[id] || 0) + prod[id]; });
  Object.keys(sc).forEach(id => { total[id] = (total[id] || 0) + sc[id]; });
  return total;
}
// Per-ingredient breakdown for the Allocation cell.
function inventoryAllocationBreakdown(ingredientId) {
  const sc = supplyChainDemand()[ingredientId] || 0;
  const prod = allocatedInventory()[ingredientId] || 0;
  return { sc, prod, total: sc + prod };
}
// List of inventory conflicts: any ingredient where total allocations exceed on-hand stock.
function inventoryConflicts() {
  const alloc = allocatedInventory();
  const conflicts = [];
  state.ingredients.forEach(ing => {
    const allocAmt = alloc[ing.id] || 0;
    if (allocAmt > (ing.stock || 0)) {
      const shortBy = allocAmt - (ing.stock || 0);
      // affected POs: any allocating PO that needs this ingredient
      const affected = state.purchaseOrders.filter(po => {
        if (!isAllocating(po)) return false;
        const req = poRequirements(po);
        return (req[ing.id] || 0) > 0;
      }).map(po => ({
        po,
        need: poRequirements(po)[ing.id] || 0,
        cust: getCustomer(po.customerId)
      }));
      conflicts.push({ ingredient: ing, allocated: allocAmt, onHand: ing.stock || 0, shortBy, affected });
    }
  });
  return conflicts;
}
// Simulate finalizing a PO with its current actualQty values and report any downstream POs that would be left short.
function downstreamShortageOnFinalize(po) {
  // simulated stock after consuming this PO's actualQty
  const reqThis = poRequirements(po, true);
  const simulatedStock = {};
  state.ingredients.forEach(ing => {
    simulatedStock[ing.id] = Math.max(0, (ing.stock || 0) - (reqThis[ing.id] || 0));
  });
  // sum allocations from all OTHER allocating POs
  const downstream = [];
  const otherAlloc = allocatedInventory(po.id);
  Object.keys(otherAlloc).forEach(ingId => {
    if (otherAlloc[ingId] > simulatedStock[ingId]) {
      const ing = getIngredient(ingId);
      const short = otherAlloc[ingId] - simulatedStock[ingId];
      // who is affected
      const affected = state.purchaseOrders.filter(p => {
        if (p.id === po.id) return false;
        if (!isAllocating(p)) return false;
        const r = poRequirements(p);
        return (r[ingId] || 0) > 0;
      });
      downstream.push({ ingredient: ing, short, affected });
    }
  });
  return downstream;
}

/* js/ui/csv.js */
/* =========================================================================
   CSV EXPORT
   ========================================================================= */
function exportCsv(filename, rows) {
  if (!rows.length) { toast('Nothing to export.'); return; }
  const cols = Object.keys(rows[0]);
  const csv = [
    cols.join(','),
    ...rows.map(r => cols.map(c => {
      const v = r[c] == null ? '' : String(r[c]).replace(/"/g, '""');
      return /[",\n]/.test(v) ? `"${v}"` : v;
    }).join(','))
  ].join('\n');
  const blob = new Blob([csv], { type: 'text/csv' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url; a.download = filename;
  document.body.appendChild(a); a.click(); a.remove();
  URL.revokeObjectURL(url);
}

