/* ----- Product Calculator ----- */
let calcState = {
  productId: '',
  units: 1000,
  sizeOz: 16,
  ingredients: [],   // [{ingredientId, qtyPerUnit}]
  packaging: [],     // [{ingredientId, qtyPerUnit}]
  allergenTestPerBatch: 150,
  qaTestPerBatch: 0,
  laborHours: 8,
  laborRate: 22,
  overheadPerUnit: 0.10,
  caseCostPerUnit: 0.05,
  freightPerUnit: 0.08,
  copackFeePerUnit: 0,
  marginPct: 35
};

function renderProductCalculator(el) {
  el.innerHTML = `
    <div class="card-header">
      <h2>Product Cost Calculator</h2>
      <div>
        <button class="btn btn-secondary btn-sm" onclick="resetCalc()">Reset</button>
      </div>
    </div>
    <div class="ops-panel-body">
      <div class="help-text" style="margin-bottom:10px">Build a cost-up for any product. Pick an existing product to pre-load its formula, then tweak quantities, batch fees, labor, and margin.</div>
      <div style="margin-bottom:12px;padding:10px 14px;background:#fff5e8;border-left:3px solid var(--orange);border-radius:4px;font-size:12px;color:var(--brown)">
        <strong>Loss factor:</strong> All ingredient and packaging quantities are automatically buffered by <strong>5%</strong> to account for production loss/waste.
      </div>

      <div class="form-grid">
        <div class="form-row"><label>Load From Product</label>
          <select id="calc_product" onchange="calcLoadProduct()">
            <option value="">- Build manually -</option>
            ${state.products.map(p => `<option value="${p.id}" ${calcState.productId===p.id?'selected':''}>${escapeHtml(p.sku)} - ${escapeHtml(p.name)}</option>`).join('')}
          </select>
        </div>
        <div class="form-row"><label>Number of Units (Jars / Pouches)</label>
          <input type="number" id="calc_units" value="${calcState.units}" min="1" oninput="updateCalc()" />
        </div>
        <div class="form-row"><label>Size per Unit (oz)</label>
          <input type="number" id="calc_size" value="${calcState.sizeOz}" min="0" step="0.01" oninput="updateCalc()" />
        </div>
      </div>

      <div style="margin-top:20px">
        <div style="display:flex;justify-content:space-between;align-items:center">
          <strong style="color:var(--brown)">Ingredients (per unit)</strong>
          <button class="btn btn-secondary btn-sm" onclick="addCalcRow('ingredients')">+ Add Ingredient</button>
        </div>
        <div id="calc_ingredients" style="margin-top:8px"></div>
      </div>

      <div style="margin-top:20px">
        <div style="display:flex;justify-content:space-between;align-items:center">
          <strong style="color:var(--brown)">Packaging (per unit)</strong>
          <button class="btn btn-secondary btn-sm" onclick="addCalcRow('packaging')">+ Add Packaging</button>
        </div>
        <div id="calc_packaging" style="margin-top:8px"></div>
      </div>

      <div style="margin-top:20px;padding:16px;background:var(--beige-light);border-radius:8px">
        <strong style="color:var(--brown)">Batch Fees & Per-Unit Costs</strong>
        <div class="form-grid" style="margin-top:10px">
          <div class="form-row"><label>Allergen Testing ($/batch)</label><input type="number" id="calc_allergen" value="${calcState.allergenTestPerBatch}" step="0.01" oninput="updateCalc()" /></div>
          <div class="form-row"><label>QA / Lab Testing ($/batch)</label><input type="number" id="calc_qa" value="${calcState.qaTestPerBatch}" step="0.01" oninput="updateCalc()" /></div>
          <div class="form-row"><label>Production Labor (hours)</label><input type="number" id="calc_lhours" value="${calcState.laborHours}" step="0.25" oninput="updateCalc()" /></div>
          <div class="form-row"><label>Labor Rate ($/hr loaded)</label><input type="number" id="calc_lrate" value="${calcState.laborRate}" step="0.01" oninput="updateCalc()" /></div>
          <div class="form-row"><label>Overhead ($/unit)</label><input type="number" id="calc_oh" value="${calcState.overheadPerUnit}" step="0.01" oninput="updateCalc()" /></div>
          <div class="form-row"><label>Case / Carton ($/unit)</label><input type="number" id="calc_case" value="${calcState.caseCostPerUnit}" step="0.01" oninput="updateCalc()" /></div>
          <div class="form-row"><label>Freight Allocation ($/unit)</label><input type="number" id="calc_freight" value="${calcState.freightPerUnit}" step="0.01" oninput="updateCalc()" /></div>
          <div class="form-row"><label>Co-Pack Fee ($/unit)</label><input type="number" id="calc_copack" value="${calcState.copackFeePerUnit}" step="0.01" oninput="updateCalc()" /></div>
          <div class="form-row"><label>Target Margin %</label><input type="number" id="calc_margin" value="${calcState.marginPct}" step="1" oninput="updateCalc()" /></div>
        </div>
      </div>

      <div id="calc_summary" style="margin-top:20px"></div>
    </div>
  `;
  renderCalcRows('ingredients');
  renderCalcRows('packaging');
  updateCalc();
}

function loadProductIntoCalc(productId) {
  productsTab = 'calc';
  calcState.productId = productId;
  router('products');
  // hand-off after render
  setTimeout(() => {
    const sel = document.getElementById('calc_product');
    if (sel) { sel.value = productId; calcLoadProduct(); }
  }, 30);
}

function calcLoadProduct() {
  const id = document.getElementById('calc_product').value;
  calcState.productId = id;
  if (!id) { updateCalc(); return; }
  const p = getProduct(id);
  const bom = state.boms[id] || [];
  // split BOM into ingredient rows vs packaging rows by unit ('ea' = packaging-ish)
  calcState.ingredients = [];
  calcState.packaging = [];
  bom.forEach(b => {
    const ing = getIngredient(b.ingredientId);
    if (!ing) return;
    const row = { ingredientId: b.ingredientId, qtyPerUnit: b.qty };
    if (ing.unit === 'ea') calcState.packaging.push(row);
    else calcState.ingredients.push(row);
  });
  if (p && p.size) calcState.sizeOz = p.size;
  document.getElementById('calc_size').value = calcState.sizeOz;
  renderCalcRows('ingredients');
  renderCalcRows('packaging');
  updateCalc();
}

function renderCalcRows(kind) {
  const cont = document.getElementById('calc_'+kind);
  if (!cont) return;
  const rows = calcState[kind];
  if (rows.length === 0) {
    cont.innerHTML = `<div style="font-size:12px;color:var(--brown-light);padding:10px 0">No ${kind} added.</div>`;
    return;
  }
  cont.innerHTML = `
    <div class="po-line" style="font-size:11px;color:var(--brown-light);text-transform:uppercase;font-weight:600">
      <div>Item</div><div>Qty / Unit</div><div>Unit Cost</div><div>Subtotal (+5% loss)</div><div></div>
    </div>
    ${rows.map((r, i) => {
      const ing = getIngredient(r.ingredientId);
      const sub = (ing ? ing.cost : 0) * r.qtyPerUnit * LOSS_FACTOR;
      return `<div class="po-line">
        <select onchange="calcRowChange('${kind}',${i},'ingredientId',this.value)">
          <option value="">- Select -</option>
          ${state.ingredients.map(opt => `<option value="${opt.id}" ${r.ingredientId===opt.id?'selected':''}>${escapeHtml(opt.name)} (${escapeHtml(opt.unit)})</option>`).join('')}
        </select>
        <input type="number" min="0" step="0.001" value="${r.qtyPerUnit}" oninput="calcRowChange('${kind}',${i},'qtyPerUnit',this.value)" />
        <div style="text-align:right;color:var(--brown-light);font-size:13px">${ing ? fmtMoney(ing.cost) : '-'}</div>
        <div style="text-align:right;font-weight:600;color:var(--brown)">${fmtMoney(sub)}</div>
        <button type="button" onclick="removeCalcRow('${kind}',${i})">&times;</button>
      </div>`;
    }).join('')}
  `;
}
function addCalcRow(kind) {
  calcState[kind].push({ ingredientId: '', qtyPerUnit: 0 });
  renderCalcRows(kind);
  updateCalc();
}
function removeCalcRow(kind, idx) {
  calcState[kind].splice(idx, 1);
  renderCalcRows(kind);
  updateCalc();
}
function calcRowChange(kind, idx, field, value) {
  if (field === 'qtyPerUnit') value = parseFloat(value) || 0;
  calcState[kind][idx][field] = value;
  // re-render to refresh subtotal display
  renderCalcRows(kind);
  updateCalc();
}
function readCalcInputs() {
  calcState.units = parseFloat(document.getElementById('calc_units').value) || 0;
  calcState.sizeOz = parseFloat(document.getElementById('calc_size').value) || 0;
  calcState.allergenTestPerBatch = parseFloat(document.getElementById('calc_allergen').value) || 0;
  calcState.qaTestPerBatch = parseFloat(document.getElementById('calc_qa').value) || 0;
  calcState.laborHours = parseFloat(document.getElementById('calc_lhours').value) || 0;
  calcState.laborRate = parseFloat(document.getElementById('calc_lrate').value) || 0;
  calcState.overheadPerUnit = parseFloat(document.getElementById('calc_oh').value) || 0;
  calcState.caseCostPerUnit = parseFloat(document.getElementById('calc_case').value) || 0;
  calcState.freightPerUnit = parseFloat(document.getElementById('calc_freight').value) || 0;
  calcState.copackFeePerUnit = parseFloat(document.getElementById('calc_copack').value) || 0;
  calcState.marginPct = parseFloat(document.getElementById('calc_margin').value) || 0;
}
const LOSS_FACTOR = 1.05; // 5% loss applied to ingredients & packaging
function calcSubtotal(kind) {
  return calcState[kind].reduce((s, r) => {
    const ing = getIngredient(r.ingredientId);
    return s + (ing ? ing.cost : 0) * r.qtyPerUnit * LOSS_FACTOR;
  }, 0);
}
function calcSubtotalRaw(kind) {
  return calcState[kind].reduce((s, r) => {
    const ing = getIngredient(r.ingredientId);
    return s + (ing ? ing.cost : 0) * r.qtyPerUnit;
  }, 0);
}
function updateCalc() {
  if (!document.getElementById('calc_units')) return;
  readCalcInputs();
  const units = calcState.units;
  const ingPerUnit = calcSubtotal('ingredients');
  const pkgPerUnit = calcSubtotal('packaging');
  const laborTotal = calcState.laborHours * calcState.laborRate;
  const laborPerUnit = units ? laborTotal / units : 0;
  const allergenPerUnit = units ? calcState.allergenTestPerBatch / units : 0;
  const qaPerUnit = units ? calcState.qaTestPerBatch / units : 0;
  const overheadPerUnit = calcState.overheadPerUnit;
  const casePerUnit = calcState.caseCostPerUnit;
  const freightPerUnit = calcState.freightPerUnit;
  const copackPerUnit = calcState.copackFeePerUnit;

  const totalPerUnit = ingPerUnit + pkgPerUnit + laborPerUnit + allergenPerUnit + qaPerUnit + overheadPerUnit + casePerUnit + freightPerUnit + copackPerUnit;
  const batchTotal = totalPerUnit * units;
  const margin = calcState.marginPct / 100;
  const wholesale = margin < 1 && margin > 0 ? totalPerUnit / (1 - margin) : totalPerUnit;
  const wholesaleBatch = wholesale * units;
  const profitPerUnit = wholesale - totalPerUnit;
  const profitTotal = profitPerUnit * units;
  const costPerOz = calcState.sizeOz > 0 ? totalPerUnit / calcState.sizeOz : 0;

  const sum = document.getElementById('calc_summary');
  sum.innerHTML = `
    <div style="background:var(--white);border:2px solid var(--orange);border-radius:10px;padding:18px">
      <h3 style="margin:0 0 12px;color:var(--brown)">Cost Summary</h3>
      <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:14px">
        ${costRow('Ingredients / unit', ingPerUnit, '(incl. 5% loss)')}
        ${costRow('Packaging / unit', pkgPerUnit, '(incl. 5% loss)')}
        ${costRow('Labor / unit', laborPerUnit, `(${laborTotal.toFixed(2)} batch)`)}
        ${costRow('Allergen test / unit', allergenPerUnit, `(${calcState.allergenTestPerBatch.toFixed(2)} batch)`)}
        ${costRow('QA / Lab / unit', qaPerUnit, `(${calcState.qaTestPerBatch.toFixed(2)} batch)`)}
        ${costRow('Overhead / unit', overheadPerUnit)}
        ${costRow('Case / Carton / unit', casePerUnit)}
        ${costRow('Freight / unit', freightPerUnit)}
        ${costRow('Co-Pack fee / unit', copackPerUnit)}
      </div>
      <hr style="margin:14px 0;border:none;border-top:1px solid var(--grey-light)" />
      <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:14px">
        <div class="stat brown" style="margin:0"><div class="label">Total Cost / Unit</div><div class="value">${fmtMoney(totalPerUnit)}</div></div>
        <div class="stat" style="margin:0"><div class="label">Cost / oz</div><div class="value">${fmtMoney(costPerOz)}</div></div>
        <div class="stat" style="margin:0"><div class="label">Batch Cost (${units} units)</div><div class="value">${fmtMoney(batchTotal)}</div></div>
        <div class="stat ok" style="margin:0"><div class="label">Suggested Wholesale @ ${calcState.marginPct}% margin</div><div class="value">${fmtMoney(wholesale)}</div></div>
        <div class="stat ok" style="margin:0"><div class="label">Profit / Unit</div><div class="value">${fmtMoney(profitPerUnit)}</div></div>
        <div class="stat ok" style="margin:0"><div class="label">Batch Profit</div><div class="value">${fmtMoney(profitTotal)}</div></div>
      </div>
      <div style="margin-top:14px;text-align:right;font-size:13px;color:var(--brown-light)">
        Total batch revenue at suggested wholesale: <strong style="color:var(--brown)">${fmtMoney(wholesaleBatch)}</strong>
      </div>
    </div>
  `;
}
function costRow(label, perUnit, extra='') {
  return `<div style="display:flex;justify-content:space-between;font-size:13px">
    <span style="color:var(--brown-light)">${label} ${extra ? `<span style="font-size:11px">${escapeHtml(extra)}</span>`:''}</span>
    <span style="font-weight:600;color:var(--brown)">${fmtMoney(perUnit)}</span>
  </div>`;
}
async function resetCalc() {
  const ok = await openConfirmModal({
    title: 'Reset calculator',
    record: 'Product Calculator',
    message: 'Reset all calculator inputs?',
    risk: 'Unsaved calculator entries will be cleared.',
    confirmLabel: 'Reset Calculator',
    tone: 'danger'
  });
  if (!ok) return;
  calcState = {
    productId: '', units: 1000, sizeOz: 16,
    ingredients: [], packaging: [],
    allergenTestPerBatch: 150, qaTestPerBatch: 0,
    laborHours: 8, laborRate: 22,
    overheadPerUnit: 0.10, caseCostPerUnit: 0.05,
    freightPerUnit: 0.08, copackFeePerUnit: 0,
    marginPct: 35
  };
  renderProductCalculator(document.getElementById('productsBody'));
}

/* js/modules/users/index.js */
/* =========================================================================
   ACCOUNT MANAGEMENT (Users)
   ========================================================================= */
function backendAuthPanelHtml() {
  const signedIn = !!backendAuthState.token && !!backendAuthState.user;
  const roles = signedIn ? (backendAuthState.roles || []).join(', ') : '';
  const userLabel = signedIn
    ? `${escapeHtml(backendAuthState.user.displayName || backendAuthState.user.email)}${roles ? ' - ' + escapeHtml(roles) : ''}`
    : 'Backend session inactive';
  const statusText = backendUserState.status === 'connected'
    ? 'Backend Account Management is connected.'
    : backendUserState.status === 'error'
      ? escapeHtml(backendUserState.lastError || BACKEND_READ_FAILED_MESSAGE)
      : 'Create the first admin or log in as backend Admin before adding users. Browser-preview users cannot log in.';
  return `
    <div class="inv-check ${signedIn ? 'ok' : ''}" data-auth-panel="account-management" style="margin-bottom:12px;border-left-color:${signedIn ? 'var(--success)' : 'var(--orange)'}">
      <div style="display:flex;justify-content:space-between;gap:10px;align-items:center;flex-wrap:wrap">
        <div>
          <strong>Account access</strong>
          <div class="help-text">${statusText}</div>
          <div style="font-size:12px;color:var(--brown);margin-top:4px">${userLabel}</div>
        </div>
        <div style="display:flex;gap:6px;flex-wrap:wrap">
          ${signedIn ? `<button class="btn btn-secondary btn-sm" onclick="refreshBackendAuth()">Refresh Session</button><button class="btn btn-secondary btn-sm" onclick="logoutBackendAuth()">Logout</button>` : `<button class="btn btn-sm" onclick="openBackendLogin()">Login</button>`}
        </div>
      </div>
    </div>`;
}

async function refreshBackendAuth() {
  if (!backendAuthState.token) { openBackendLogin(); return; }
  try {
    const data = await apiRequest('/api/auth/me');
    setBackendAuth({ token: backendAuthState.token, ...data });
    await loadBackendUsers();
    toast('Backend session refreshed.');
    enterAuthenticatedApp(isPageAllowedForCurrentUser(currentPage) ? currentPage : roleLandingPageForCurrentUser());
  } catch (err) {
    clearBackendAuth();
    backendUserState.status = 'error';
    backendUserState.lastError = 'Backend auth session expired or unavailable.';
    showAuthGate('Session expired or was rejected. Please sign in again.');
    toast('Backend session unavailable. Please sign in again.');
  }
}

async function checkBackendSetupStatus() {
  return apiRequest('/api/auth/setup-status');
}

function openBackendSetup() {
  openModal('First Admin Setup', `
    <div id="auth_setup_status" class="help-text" style="margin-bottom:12px">Checking backend setup status...</div>
    <div class="help-text" style="margin-bottom:12px">Creates the first backend Admin only when the D1 users table is empty. If setup is already complete, use Login instead.</div>
    <form onsubmit="event.preventDefault();submitBackendSetup()">
      <div class="form-grid">
        <div class="form-row"><label>Full Name</label><input id="auth_setup_name" required /></div>
        <div class="form-row"><label>Email</label><input type="email" id="auth_setup_email" required /></div>
        <div class="form-row"><label>Password</label><input type="password" id="auth_setup_password" minlength="8" required /></div>
      </div>
      <div class="form-actions">
        <button type="button" class="btn btn-secondary" onclick="closeModal()">Cancel</button>
        <button type="submit" class="btn">Create Admin</button>
      </div>
    </form>
  `);
  checkBackendSetupStatus()
    .then(status => {
      const el = document.getElementById('auth_setup_status');
      if (el) el.textContent = status.needsSetup ? 'First admin setup is available.' : 'Backend setup is already complete; use Login.';
    })
    .catch(() => {
      const el = document.getElementById('auth_setup_status');
      if (el) el.textContent = 'Setup status is unavailable right now; use an approved sample account or retry.';
    });
}

async function submitBackendSetup() {
  try {
    const data = await apiRequest('/api/auth/setup', {
      method: 'POST',
      body: JSON.stringify({
        displayName: document.getElementById('auth_setup_name').value,
        email: document.getElementById('auth_setup_email').value,
        password: document.getElementById('auth_setup_password').value
      })
    });
    setBackendAuth(data);
    closeModal();
    await loadBackendUsers();
    enterAuthenticatedApp(roleLandingPageForCurrentUser());
    toast('Backend Admin created and signed in.');
  } catch (err) {
    toast(err.message || 'Backend setup failed.');
  }
}

function openBackendLogin() {
  openModal('Backend Login', `
    <div class="help-text" style="margin-bottom:12px">Use an approved staging sample account. Signing in loads protected backend records and role-based access.</div>
    <form onsubmit="event.preventDefault();submitBackendLogin(event.currentTarget)">
      <div class="form-grid">
        <div class="form-row"><label>Email</label><input type="email" id="auth_login_email" required /></div>
        <div class="form-row"><label>Password</label><input type="password" id="auth_login_password" required /></div>
      </div>
      <div class="form-actions">
        <button type="button" class="btn btn-secondary" onclick="closeModal()">Cancel</button>
        <button type="submit" class="btn">Login</button>
      </div>
    </form>
  `);
}

async function submitBackendLogin(form) {
  try {
    const emailInput = form?.querySelector?.('input[type="email"]') || document.getElementById('auth_login_email') || document.getElementById('auth_gate_email');
    const passwordInput = form?.querySelector?.('input[type="password"]') || document.getElementById('auth_login_password') || document.getElementById('auth_gate_password');
    const data = await apiRequest('/api/auth/login', {
      method: 'POST',
      body: JSON.stringify({
        email: emailInput?.value || '',
        password: passwordInput?.value || ''
      })
    });
    setBackendAuth(data);
    closeModal();
    await loadBackendUsers();
    enterAuthenticatedApp(roleLandingPageForCurrentUser());
    toast('Signed in to backend account API.');
  } catch (err) {
    toast(err.message || 'Login failed.');
  }
}

async function logoutBackendAuth() {
  try {
    if (backendAuthState.token) await apiRequest('/api/auth/logout', { method: 'POST' });
  } catch (err) {}
  clearBackendAuth();
  showAuthGate('Signed out. Sign in to open the ERP.');
  toast('Logged out. Sign in again to load protected backend records.');
}

function backendUserToLocalUser(user) {
  const role = (user.roles || [])[0] || 'Sales';
  return {
    id: user.id,
    _backendUserId: user.id,
    name: user.displayName || user.email,
    email: user.email || '',
    role,
    customerId: role === 'Customer' ? (user.customerAccess?.[0]?.customerId || '') : '',
    addedAt: (user.createdAt || '').slice(0, 10),
    isActive: user.isActive !== false
  };
}

function upsertLocalUserFromBackend(user) {
  if (user.isActive === false) {
    state.users = (state.users || []).filter(u => u._backendUserId !== user.id && u.id !== user.id);
    return;
  }
  const mapped = backendUserToLocalUser(user);
  state.users = state.users || [];
  const existing = state.users.find(u => u._backendUserId === user.id || u.id === user.id || (u.email && u.email.toLowerCase() === (user.email || '').toLowerCase()));
  if (existing) Object.assign(existing, mapped);
  else state.users.push(mapped);
}

function customerDisplayNameForUser(user) {
  if (user.role !== 'Customer') return '-';
  if (!user.customerId) return '';
  const linked = getCustomer(user.customerId);
  if (linked?.name) return linked.name;
  if (user.customerId === 'customer_demo_1') return 'Customer Demo 1';
  return user.customerId;
}

function linkedCustomerCellHtml(user) {
  if (user.role !== 'Customer') return '<span style="color:var(--brown-light);font-size:12px">-</span>';
  const label = customerDisplayNameForUser(user);
  return label ? escapeHtml(label) : '<span style="color:var(--danger);font-size:12px">Not linked</span>';
}

function canManageBackendUsers() {
  return (backendAuthState.roles || []).includes('Admin');
}

async function loadBackendUsers() {
  if (!backendAuthState.token || backendUserState.loadingUsers) return;
  if (!canManageBackendUsers()) {
    clearProtectedBackendRows('account-management');
    backendUserState.status = 'connected';
    backendUserState.lastError = 'Customer backend session active; admin user list is hidden.';
    return;
  }
  backendUserState.loadingUsers = true;
  try {
    const users = await apiRequest('/api/users');
    (users || []).forEach(upsertLocalUserFromBackend);
    backendUserState.status = 'connected';
    backendUserState.lastError = '';
    saveState();
  } catch (err) {
    clearProtectedBackendRows('account-management');
    setBackendReadFailed(backendUserState);
  } finally {
    backendUserState.loadingUsers = false;
  }
}

function renderUsers(el) {
  if (backendAuthState.token && backendUserState.status !== 'connected' && !backendUserState.loadingUsers) {
    loadBackendUsers().then(() => { if (currentPage === 'users') router('users'); });
  }
  el.innerHTML = `
    ${backendAuthPanelHtml()}
    <div class="card">
      <div class="card-header">
        <h2>Account Management</h2>
        <div>
          <button class="btn btn-secondary btn-sm" onclick="exportCsv('users.csv', state.users)">Export CSV</button>
          <button class="btn" onclick="editUser()" ${canManageBackendUsers() ? '' : 'disabled title="Log in as backend Admin before adding users"'}>+ Add User</button>
        </div>
      </div>
      <div class="help-text" style="margin-bottom:8px">Add team members and assign permissions. Roles now match the Phase 2A backend model; server-side enforcement is active when AUTH_REQUIRED=true.</div>
      <div class="table-wrap"><table>
        <thead><tr>
          <th>Name</th><th>Email</th><th>Role</th><th>Linked Customer</th><th>Added</th><th></th>
        </tr></thead>
        <tbody>
          ${((state.users||[]).filter(u => u.isActive !== false)).length === 0 ? `<tr><td colspan="6" class="empty">No users yet.</td></tr>` :
            (state.users||[]).filter(u => u.isActive !== false).map(u => {
              const linked = u.role === 'Customer' ? getCustomer(u.customerId) : null;
              return `
              <tr>
                <td><strong>${escapeHtml(u.name)}</strong></td>
                <td><a href="mailto:${escapeHtml(u.email||'')}" style="color:var(--orange)">${escapeHtml(u.email||'')}</a></td>
                <td><span class="badge ${u.role==='Admin'?'badge-prod':u.role==='Customer'?'badge-shipping':'badge-supply'}">${escapeHtml(u.role||'')}</span></td>
                <td>${linkedCustomerCellHtml(u)}</td>
                <td>${fmtDate(u.addedAt)}</td>
                <td class="row-actions">
                  ${u.role === 'Customer' && linked ? `<button class="btn btn-icon btn-sm" onclick="viewCustomerPortal('${u.customerId}')">View Portal</button>` : ''}
                  <button class="btn btn-icon btn-sm" onclick="editUser('${u.id}')">Edit</button>
                  <button class="btn btn-icon btn-sm" style="color:var(--danger)" onclick="deleteUser('${u.id}')">Remove</button>
                </td>
              </tr>
            `;}).join('')
          }
        </tbody>
      </table></div>
    </div>
    <div class="card">
      <h3 style="margin:0 0 8px">Permission Levels</h3>
      <div class="help-text" style="margin-bottom:10px">These roles are available when adding or editing a user.</div>
      <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:10px">
        ${USER_ROLES.map(r => `
          <div style="border:1px solid var(--grey-light);border-radius:8px;padding:10px;background:var(--beige-light)">
            <div style="font-weight:700;color:var(--brown);margin-bottom:4px">${escapeHtml(r)}</div>
            <div style="font-size:12px;color:var(--brown-light)">${roleDescription(r)}</div>
          </div>
        `).join('')}
      </div>
    </div>
  `;
}
function roleDescription(r) {
  switch(r) {
    case 'Admin': return 'Full access to all sections including user management.';
    case 'Sales': return 'Customers, Purchase Orders, Products. View Shipping.';
    case 'Supply Chain & Procurement': return 'Supply Chain, Procurement, Suppliers, Inventory.';
    case 'Warehousing': return 'Inventory, Shipping, Pick & Pack, Quality, and Production Schedule workflows.';
    case 'Production': return 'Production Schedule, Food Safety. View Inventory.';
    case 'Customer': return 'External - sees only their own customer profile, their own POs (open & completed), and packaging + finished goods inventory tied to their products.';
    default: return '';
  }
}
function editUser(id) {
  const u = (state.users||[]).find(x=>x.id===id) || { id: uid('u'), name:'', email:'', role:'Sales', customerId:'', addedAt: '' };
  const isNew = !id;
  const passwordPlaceholder = isNew ? 'Required for new backend users' : 'Optional: set a new temporary password';
  openModal((isNew?'Add':'Edit')+' User', `
    <form onsubmit="event.preventDefault();saveUser('${u.id}', ${isNew})">
      <div class="form-grid">
        <div class="form-row"><label>Full Name</label><input id="usr_name" value="${escapeHtml(u.name)}" required /></div>
        <div class="form-row"><label>Email</label><input type="email" id="usr_email" value="${escapeHtml(u.email)}" required /></div>
        <div class="form-row"><label>Role / Permission Level</label>
          <select id="usr_role" required onchange="toggleCustomerLink()">
            ${USER_ROLES.map(r=>`<option ${u.role===r?'selected':''}>${escapeHtml(r)}</option>`).join('')}
          </select>
        </div>
        <div class="form-row"><label>Added Date</label><input type="text" id="usr_added" value="${escapeHtml(u.addedAt || 'Pending backend save')}" readonly /></div>
        <div class="form-row"><label>Temporary Password</label><input type="password" id="usr_password" minlength="8" placeholder="${passwordPlaceholder}" /></div>
      </div>
      <div class="form-row" id="usr_customer_row" style="margin-top:12px;display:${u.role==='Customer'?'flex':'none'}">
        <label>Linked Customer Account *</label>
        <select id="usr_customer">
          <option value="">- Select Customer -</option>
          ${state.customers.map(c=>`<option value="${c.id}" ${u.customerId===c.id?'selected':''}>${escapeHtml(c.name)}</option>`).join('')}
        </select>
        <div class="help-text">Required for Customer role. The user will only see data tied to this customer.</div>
      </div>
      <div class="form-actions">
        <button type="button" class="btn btn-secondary" onclick="closeModal()">Cancel</button>
        <button type="submit" class="btn">${isNew?'Add User':'Save Changes'}</button>
      </div>
    </form>
  `);
}
function toggleCustomerLink() {
  const role = document.getElementById('usr_role').value;
  document.getElementById('usr_customer_row').style.display = (role === 'Customer') ? 'flex' : 'none';
}
async function saveUser(id, isNew) {
  const role = document.getElementById('usr_role').value;
  const customerId = document.getElementById('usr_customer')?.value || '';
  if (role === 'Customer' && !customerId) { toast('Pick a customer to link this account to.'); return; }
  const data = {
    id,
    name: document.getElementById('usr_name').value,
    email: document.getElementById('usr_email').value,
    role,
    customerId: role === 'Customer' ? customerId : '',
    addedAt: document.getElementById('usr_added').value
  };

  if (!requireBackendWriteSession(backendUserState, 'Log in as backend Admin before saving users. Nothing was saved locally.')) return;
  try {
    const existing = (state.users || []).find(u => u.id === id);
    const password = document.getElementById('usr_password')?.value || '';
    let saved;
    if (isNew) {
      if (password.length < 8) { toast('Temporary password must be at least 8 characters for backend users.'); return; }
      saved = await apiRequest('/api/users', {
        method: 'POST',
        body: JSON.stringify({ email: data.email, displayName: data.name, password, roles: [role], customerId: data.customerId || undefined })
      });
    } else {
      if (password && password.length < 8) { toast('Temporary password must be at least 8 characters.'); return; }
      const patchBody = { email: data.email, displayName: data.name, roles: [role], customerId: data.customerId || undefined, isActive: true };
      if (password) patchBody.temporaryPassword = password;
      const backendId = existing?._backendUserId || id;
      saved = await apiRequest(`/api/users/${encodeURIComponent(backendId)}`, {
        method: 'PATCH',
        body: JSON.stringify(patchBody)
      });
    }
    upsertLocalUserFromBackend(saved);
    backendUserState.status = 'connected';
    backendUserState.lastError = '';
    saveState();
    closeModal();
    router('users');
    toast('User saved to backend.');
    return;
  } catch (err) {
    failBackendRequiredWrite(err, backendUserState, 'Backend user save failed. The account was not created; log in as backend Admin and try again.');
    return;
  }
}

/* js/modules/customer-portal/index.js */
/* ----- Customer Portal preview ----- */
let customerPortalPageRequestId = 0;

function viewCustomerPortalPreview(customerId) {
  const cust = getCustomer(customerId);
  if (!cust) { toast('Customer not found.'); return; }
  // POs for this customer
  const myPos = state.purchaseOrders.filter(p => p.customerId === customerId);
  const openPos = myPos.filter(p => p.status !== 'completed');
  const donePos = myPos.filter(p => p.status === 'completed');
  // Products linked to this customer
  const myProducts = state.products.filter(p => p.customerId === customerId);

  openModal(`Customer Portal Preview - ${escapeHtml(cust.name)}`, `
    <div style="background:var(--beige-light);padding:10px;border-radius:6px;margin-bottom:14px;font-size:12px;color:var(--brown)">
      <strong>Preview only.</strong> This is what a Customer-role user linked to <strong>${escapeHtml(cust.name)}</strong> would see when they log in. Backend customer scoping is available when AUTH_REQUIRED=true; this preview stays local for stakeholder review.
    </div>
    <h3 style="margin:0 0 6px;color:var(--brown)">Account Info</h3>
    <table style="margin-bottom:14px">
      <tbody>
        <tr><td style="font-weight:600;width:140px">Company</td><td>${escapeHtml(cust.name)}</td></tr>
        <tr><td style="font-weight:600">Contact</td><td>${escapeHtml(cust.contact||'-')}</td></tr>
        <tr><td style="font-weight:600">Email</td><td>${escapeHtml(cust.email||'-')}</td></tr>
        <tr><td style="font-weight:600">Phone</td><td>${escapeHtml(cust.phone||'-')}</td></tr>
        <tr><td style="font-weight:600">Address</td><td>${escapeHtml(cust.address||'-')}</td></tr>
      </tbody>
    </table>

    <h3 style="margin:0 0 6px;color:var(--brown)">Open Purchase Orders (${openPos.length})</h3>
    ${openPos.length === 0 ? '<div class="empty" style="padding:14px">No open POs.</div>' : `
      <div class="table-wrap"><table style="margin-bottom:14px">
        <thead><tr><th>PO #</th><th>Date</th><th>Items</th><th>Total</th><th>Status</th></tr></thead>
        <tbody>
        ${openPos.map(p => `<tr>
          <td><strong>${p.id}</strong></td>
          <td>${fmtDate(p.poDate)}</td>
          <td>${p.lines.length}</td>
          <td>${fmtMoney(p.lines.reduce((s,l)=>s+l.qty*l.price,0))}</td>
          <td>${statusBadge(p.status)}</td>
        </tr>`).join('')}
        </tbody>
      </table></div>`
    }

    <h3 style="margin:0 0 6px;color:var(--brown)">Completed Purchase Orders (${donePos.length})</h3>
    ${donePos.length === 0 ? '<div class="empty" style="padding:14px">No completed POs.</div>' : `
      <div class="table-wrap"><table style="margin-bottom:14px">
        <thead><tr><th>PO #</th><th>Date</th><th>Items</th><th>Total</th><th>BOL #</th></tr></thead>
        <tbody>
        ${donePos.map(p => `<tr>
          <td><strong>${p.id}</strong></td>
          <td>${fmtDate(p.poDate)}</td>
          <td>${p.lines.length}</td>
          <td>${fmtMoney(p.lines.reduce((s,l)=>s+l.qty*l.price,0))}</td>
          <td>${escapeHtml(p.shipping?.bol||'-')}</td>
        </tr>`).join('')}
        </tbody>
      </table></div>`
    }

    <h3 style="margin:0 0 6px;color:var(--brown)">Finished Goods (Your SKUs)</h3>
    ${myProducts.length === 0 ? '<div class="empty" style="padding:14px">No products linked yet.</div>' : `
      <div class="table-wrap"><table style="margin-bottom:14px">
        <thead><tr><th>SKU</th><th>Name</th><th>Size</th><th>Production Room</th></tr></thead>
        <tbody>
        ${myProducts.map(p => `<tr>
          <td><strong>${escapeHtml(p.sku)}</strong></td>
          <td>${escapeHtml(p.name)}</td>
          <td>${p.size ? escapeHtml(p.size+(p.sizeUnit||'oz')) : '-'}</td>
          <td>${escapeHtml(p.room||'-')}</td>
        </tr>`).join('')}
        </tbody>
      </table></div>`
    }

    <div class="form-actions">
      <button class="btn btn-secondary" onclick="closeModal()">Close Preview</button>
    </div>
  `);
}

function viewSignedInCustomerPortal() {
  const access = (backendAuthState.customerAccess || [])[0];
  if (!access?.customerId) { toast('No linked customer on this account session.'); return; }
  viewCustomerPortal(access.customerId);
}

async function loadCustomerPortalData(customerId) {
  let cust = getCustomer(customerId) || { id: customerId, name: customerId, contact: '', email: '', phone: '', address: '' };
  let backendConnected = false;
  let portalError = '';
  if (backendAuthState.token) {
    try {
      if (backendAuthState.user?.userType === 'customer') {
        const profile = await loadBackendCustomerProfile();
        if (profile?.id) customerId = profile.id;
      } else {
        await loadBackendCustomers();
      }
      await loadBackendProducts();
      await refreshBackendPurchaseOrders();
      cust = getCustomer(customerId) || cust;
      backendConnected = backendApiState.status === 'connected';
    } catch (error) {
      markBackendUnavailable(error);
      portalError = error?.message || 'Backend portal data unavailable.';
    }
  }
  return { customerId, cust, backendConnected, portalError };
}

async function viewCustomerPortal(customerId) {
  let cust = getCustomer(customerId) || { id: customerId, name: customerId, contact: '', email: '', phone: '', address: '' };
  openModal(`Customer Portal - ${escapeHtml(cust.name)}`, '<div class="empty">Loading customer portal...</div>');
  const portal = await loadCustomerPortalData(customerId);
  renderCustomerPortalModal(portal.customerId, portal.cust, portal.backendConnected, portal.portalError);
}

async function renderSignedInCustomerPortalPage(el) {
  const requestId = ++customerPortalPageRequestId;
  const access = (backendAuthState.customerAccess || [])[0];
  if (!access?.customerId) {
    el.innerHTML = renderOpsPanel({
      title: 'Customer Portal',
      kicker: 'Customer access',
      body: `
        <div class="empty">
          <strong>Customer link unavailable.</strong>
          <p>This account session is not linked to a customer account. Ask an Admin to link this login to the correct customer record.</p>
        </div>`
    });
    return;
  }
  el.innerHTML = `
    <div class="customer-portal">
      <div class="empty" style="padding:14px">Loading customer portal...</div>
    </div>`;
  const portal = await loadCustomerPortalData(access.customerId);
  if (requestId !== customerPortalPageRequestId || currentPage !== 'customer-portal') return;
  renderCustomerPortalInline(el, portal.customerId, portal.cust, portal.backendConnected, portal.portalError);
}

